initJs:
function(container, apiUrl, tables) {
  let currentPage = 1;
  let itemsPerPage = 20;
  let allLogs = [];
  let filteredLogs = [];
  let autoRefreshInterval = null;

  // テーブル再描画関数
  function renderRows(logs) {
    const tbody = container.querySelector('#log-table-body');
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageData = logs.slice(startIndex, endIndex);

    tbody.innerHTML = pageData.map(log => {
      const statusClass = getStatusClass(log.処理ステータス || '');
      const statusBadge = `<span class="status-badge ${statusClass}">${log.処理ステータス || '-'}</span>`;

      return `
        <tr data-id="${log.ログID}" class="log-row">
          <td>${formatDateTime(log.収集開始日時)}</td>
          <td>${log.データ種別 || '-'}</td>
          <td>${log.データソース || '-'}</td>
          <td>${log.店舗名 || '-'}</td>
          <td>${statusBadge}</td>
          <td>${log.収集件数 || 0}</td>
          <td>${log.エラー件数 || 0}</td>
          <td>${log.処理時間秒 || 0}秒</td>
          <td>${log.データ品質スコア || '-'}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${log.ログID}">詳細</button>
            ${(log.処理ステータス === '失敗' && log.再実行フラグ) ? 
              `<button class="action-btn retry-btn" data-id="${log.ログID}">再実行</button>` : ''}
          </td>
        </tr>
      `;
    }).join('');

    updateLogCount(logs.length);
    renderPagination(logs.length);
  }

  function getStatusClass(status) {
    switch(status) {
      case '成功': return 'status-success';
      case '失敗': return 'status-error';
      case '警告': return 'status-warning';
      case '実行中': return 'status-running';
      default: return '';
    }
  }

  function formatDateTime(dateStr) {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP');
  }

  function updateLogCount(count) {
    container.querySelector('#log-count-display').textContent = `${count}件`;
  }

  function renderPagination(totalItems) {
    const totalPages = Math.ceil(totalItems / itemsPerPage);
    const pagination = container.querySelector('#pagination');

    if (totalPages <= 1) {
      pagination.innerHTML = '';
      return;
    }

    let paginationHTML = `
      <button ${currentPage === 1 ? 'disabled' : ''} id="prev-page">前へ</button>
    `;

    const startPage = Math.max(1, currentPage - 2);
    const endPage = Math.min(totalPages, currentPage + 2);

    for (let i = startPage; i <= endPage; i++) {
      paginationHTML += `
        <button class="page-btn ${i === currentPage ? 'active' : ''}" data-page="${i}">${i}</button>
      `;
    }

    paginationHTML += `
      <button ${currentPage === totalPages ? 'disabled' : ''} id="next-page">次へ</button>
    `;

    pagination.innerHTML = paginationHTML;
  }

  // サマリー情報更新
  function updateSummary(logs) {
    const today = new Date().toDateString();
    const todayLogs = logs.filter(log => {
      const logDate = new Date(log.収集開始日時);
      return logDate.toDateString() === today;
    });

    const successCount = todayLogs.filter(log => log.処理ステータス === '成功').length;
    const errorCount = todayLogs.filter(log => log.処理ステータス === '失敗').length;
    const successRate = todayLogs.length > 0 ? Math.round((successCount / todayLogs.length) * 100) : 0;

    container.querySelector('#today-count').textContent = todayLogs.length;
    container.querySelector('#success-rate').textContent = `${successRate}%`;
    container.querySelector('#error-count').textContent = errorCount;

    // 最新ログの日時
    const latestLog = logs.sort((a, b) => new Date(b.収集開始日時) - new Date(a.収集開始日時))[0];
    container.querySelector('#last-collection').textContent = latestLog ? 
      formatDateTime(latestLog.収集開始日時) : '-';

    // システム状態インジケーター
    const statusIndicator = container.querySelector('#system-status');
    if (errorCount > 5) {
      statusIndicator.textContent = 'エラー';
      statusIndicator.className = 'status-indicator error';
    } else if (errorCount > 0) {
      statusIndicator.textContent = '警告';
      statusIndicator.className = 'status-indicator warning';
    } else {
      statusIndicator.textContent = '正常';
      statusIndicator.className = 'status-indicator normal';
    }
  }

  // フィルタリング関数
  function applyFilters() {
    const datasource = container.querySelector('#filter-datasource').value;
    const loglevel = container.querySelector('#filter-loglevel').value;
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;
    const status = container.querySelector('#filter-status').value;
    const keyword = container.querySelector('#input-search').value.toLowerCase();

    filteredLogs = allLogs.filter(log => {
      if (datasource && log.データソース !== datasource) return false;
      if (status && log.処理ステータス !== status) return false;

      if (startDate) {
        const logDate = new Date(log.収集開始日時);
        const filterStart = new Date(startDate);
        if (logDate < filterStart) return false;
      }

      if (endDate) {
        const logDate = new Date(log.収集開始日時);
        const filterEnd = new Date(endDate);
        if (logDate > filterEnd) return false;
      }

      if (keyword) {
        const searchText = JSON.stringify(log).toLowerCase();
        if (!searchText.includes(keyword)) return false;
      }

      return true;
    });

    currentPage = 1;
    renderRows(filteredLogs);
  }

  // 詳細モーダル表示
  function showLogDetail(logId) {
    const log = allLogs.find(l => l.ログID === logId);
    if (!log) return;

    const modalBody = container.querySelector('#modal-body');
    modalBody.innerHTML = `
      <div class="detail-grid">
        <div class="detail-label">ログID:</div>
        <div class="detail-value">${log.ログID}</div>
        <div class="detail-label">データ種別:</div>
        <div class="detail-value">${log.データ種別 || '-'}</div>
        <div class="detail-label">データソース:</div>
        <div class="detail-value">${log.データソース || '-'}</div>
        <div class="detail-label">収集開始日時:</div>
        <div class="detail-value">${formatDateTime(log.収集開始日時)}</div>
        <div class="detail-label">収集終了日時:</div>
        <div class="detail-value">${formatDateTime(log.収集終了日時)}</div>
        <div class="detail-label">処理ステータス:</div>
        <div class="detail-value">${log.処理ステータス || '-'}</div>
        <div class="detail-label">対象期間:</div>
        <div class="detail-value">${formatDateTime(log.対象期間開始日)} ～ ${formatDateTime(log.対象期間終了日)}</div>
        <div class="detail-label">収集件数:</div>
        <div class="detail-value">${log.収集件数 || 0}件</div>
        <div class="detail-label">エラー件数:</div>
        <div class="detail-value">${log.エラー件数 || 0}件</div>
        <div class="detail-label">処理時間:</div>
        <div class="detail-value">${log.処理時間秒 || 0}秒</div>
        <div class="detail-label">データ品質スコア:</div>
        <div class="detail-value">${log.データ品質スコア || '-'}</div>
        <div class="detail-label">エラーメッセージ:</div>
        <div class="detail-value">${log.エラーメッセージ || '-'}</div>
        <div class="detail-label">備考:</div>
        <div class="detail-value">${log.備考 || '-'}</div>
      </div>
    `;

    container.querySelector('#log-detail-modal').style.display = 'flex';
  }

  // CSVエクスポート
  function exportCSV() {
    const headers = ['収集日時', 'データ種別', 'データソース', '店舗', 'ステータス', '収集件数', 'エラー件数', '処理時間', '品質スコア', 'エラーメッセージ'];

    let csvContent = '\uFEFF' + headers.join(',') + '\n';

    filteredLogs.forEach(log => {
      const row = [
        formatDateTime(log.収集開始日時),
        log.データ種別 || '',
        log.データソース || '',
        log.店舗名 || '',
        log.処理ステータス || '',
        log.収集件数 || 0,
        log.エラー件数 || 0,
        (log.処理時間秒 || 0) + '秒',
        log.データ品質スコア || '',
        `"${(log.エラーメッセージ || '').replace(/"/g, '""')}"`
      ];
      csvContent += row.join(',') + '\n';
    });

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `data_collection_logs_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 自動更新機能
  function toggleAutoRefresh() {
    const checkbox = container.querySelector('#auto-refresh-toggle');

    if (checkbox.checked) {
      autoRefreshInterval = setInterval(async () => {
        const logs = await window.aivicApi.list(11);
        if (logs) {
          allLogs = logs;
          updateSummary(logs);
          applyFilters();
        }
      }, 30000); // 30秒間隔
    } else {
      if (autoRefreshInterval) {
        clearInterval(autoRefreshInterval);
        autoRefreshInterval = null;
      }
    }
  }

  // 初期データ読み込み
  async function loadData() {
    const logs = await window.aivicApi.list(11);
    if (logs) {
      allLogs = logs;
      filteredLogs = logs;
      updateSummary(logs);
      renderRows(logs);
    }
  }

  // 初期表示
  loadData();

  // イベントリスナー
  container.querySelector('#btn-search').addEventListener('click', applyFilters);

  container.querySelector('#btn-clear-filter').addEventListener('click', () => {
    container.querySelector('#filter-datasource').value = '';
    container.querySelector('#filter-loglevel').value = '';
    container.querySelector('#filter-start-date').value = '';
    container.querySelector('#filter-end-date').value = '';
    container.querySelector('#filter-status').value = '';
    container.querySelector('#input-search').value = '';

    filteredLogs = allLogs;
    currentPage = 1;
    renderRows(filteredLogs);
  });

  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  container.querySelector('#auto-refresh-toggle').addEventListener('change', toggleAutoRefresh);

  container.querySelector('#btn-alert-settings').addEventListener('click', () => {
    container.querySelector('#alert-settings-modal').style.display = 'flex';
  });

  // モーダル関連
  container.querySelector('#close-modal').addEventListener('click', () => {
    container.querySelector('#log-detail-modal').style.display = 'none';
  });

  container.querySelector('#close-modal-btn').addEventListener('click', () => {
    container.querySelector('#log-detail-modal').style.display = 'none';
  });

  container.querySelector('#close-alert-modal').addEventListener('click', () => {
    container.querySelector('#alert-settings-modal').style.display = 'none';
  });

  container.querySelector('#close-alert-modal-btn').addEventListener('click', () => {
    container.querySelector('#alert-settings-modal').style.display = 'none';
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 詳細ボタン
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      showLogDetail(detailBtn.dataset.id);
      return;
    }

    // 再実行ボタン
    const retryBtn = e.target.closest('.retry-btn');
    if (retryBtn) {
      if (!confirm('データ収集処理を再実行しますか？')) return;

      const logId = retryBtn.dataset.id;
      const updated = await window.aivicApi.update(11, logId, {
        処理ステータス: '実行中',
        再実行フラグ: false,
        更新日時: new Date().toISOString()
      });

      if (updated) {
        loadData();
      }
      return;
    }

    // ログ行クリック
    const logRow = e.target.closest('.log-row');
    if (logRow && !e.target.closest('button')) {
      showLogDetail(logRow.dataset.id);
      return;
    }

    // ページネーション
    const pageBtn = e.target.closest('.page-btn');
    if (pageBtn) {
      currentPage = parseInt(pageBtn.dataset.page);
      renderRows(filteredLogs);
      return;
    }

    if (e.target.id === 'prev-page' && currentPage > 1) {
      currentPage--;
      renderRows(filteredLogs);
      return;
    }

    if (e.target.id === 'next-page') {
      const totalPages = Math.ceil(filteredLogs.length / itemsPerPage);
      if (currentPage < totalPages) {
        currentPage++;
        renderRows(filteredLogs);
      }
      return;
    }
  });

  // モーダル外クリックで閉じる
  container.querySelector('#log-detail-modal').addEventListener('click', (e) => {
    if (e.target === e.currentTarget) {
      e.currentTarget.style.display = 'none';
    }
  });

  container.querySelector('#alert-settings-modal').addEventListener('click', (e) => {
    if (e.target === e.currentTarget) {
      e.currentTarget.style.display = 'none';
    }
  });
}
